cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove: function () {
        this.StartRecycleSymbol()
        this._super();

    },

    playReelStop() {
        this._super();

        let cfg = cc.vv.gameData.getGameCfg();
        for (let i = 0; i < cfg.row; i++) {
            let symbol = this._symbols[i];
            if (symbol.GetShowId() === cfg.wildId) {
                if ((this._reelIdx === 0) || (this._reelIdx === 1 && cc.vv.gameData.GetSlotsScript().haveWildInReel(0))) {
                    symbol.playStopAnimation();
                }
            }
        }

        for (let i = 0; i < cfg.row; i++) {
            let symbol = this._symbols[i];
            if (symbol.GetShowId() === cfg.bonusId &&
                cc.vv.gameData.GetSlotsScript().haveWildInReel(0) &&
                cc.vv.gameData.GetSlotsScript().haveWildInReel(1)) {
                cc.vv.AudioManager.playEff("games/Poseidon/", "symbol_bonus", true);
                break;
            }
        }
    },

    StartRecycleSymbol() {
        //回收增加的卷轴
        let cfg = cc.vv.gameData.getGameCfg()
        if (this._symbols.length > (cfg.row + 1)) {
            this.AddCount(-(this._symbols.length - (cfg.row + 1)), 0.5, 0.5);
        }
    },

    //获取symbol的位置
    GetSymbolPosByRow: function (row) {
        let cfg = cc.vv.gameData.getGameCfg();
        if (this._symbols[row].GetShowId() === cfg.bonusId) {
            return cc.v2(0, (row + 0.5) * cfg.symbolSize.height + 12);
        } else {
            return cc.v2(0, (row + 0.5) * cfg.symbolSize.height);
        }
    },

    //reel变化尺寸的时候，需要设置高度的节点(y锚点都是0，这样设置长度都是y方向)
    //reel/mask , 
    //reels_bg/bg*,
    GetResizeHeightObjs: function () {
        let objs = []
        let mask = cc.find("mask", this.node)
        if (mask) {
            objs.push(mask)
        }

        let bg = cc.find("reels_bg/reel_bg" + (this._reelIdx + 1), this.node.parent.parent)
        if (bg) {
            objs.push(bg)
        }

        // 只增加一次
        if (this._reelIdx === 2) {
            for (let i = 1; i <= 4; i++) {
                let line = cc.find("reels_frame/line_" + i, this.node.parent.parent);
                if (line) {
                    objs.push(line);
                }
            }
        }


        return objs
    },

    //reel变化尺寸的时候，需要移动的节点
    //reels_frame/reel*/frame 
    GetResizeMoveingObjs: function () {
        let objs = []

        // 只增加一次
        if (this._reelIdx === 2) {
            let frameTop = cc.find("reels_frame/top_bg", this.node.parent.parent)
            if (frameTop) {
                objs.push(frameTop)
            }
        }

        return objs
    },

    isHaveScatter() {
        let cfg = cc.vv.gameData.getGameCfg();
        for (const symbol of this._symbols) {
            if (symbol.GetShowId() === cfg.scatterId) {
                return true;
            }
        }
        return false;
    },

    setScatterBgVisible(isOrNot) {
        let anti_bg = cc.find("mask/anti_bg", this.node);
        if (anti_bg) {
            anti_bg.active = isOrNot;
        }

        // let reel_bg = cc.find("reels_bg/reel_bg"+(this._reelIdx + 1) + "/free", this.node.parent.parent);
        // if (reel_bg) {
        //     reel_bg.active = isOrNot;
        // }
    }
});