cc.Class({
    extends: cc.Component,
    properties: {
        move_node_1: cc.Node,
        move_node_2: cc.Node,
        waikuang: cc.Node,
        xuanzhong: cc.Node,
        beishu: cc.Node,
        _commonMove: false,
        _speed: 50,
        _round: 2,      // 需要转几轮
        _needStop: false,
        _minSpeed: 800,
        _speedChangeInterval: 20,
        _targetIndex: 1,        // 结果索引 从1开始
        _endPosY: 0,
        _startPosY: 0,
        _successCallback: null,
        _beginStop: false,
        _wheelCfg: [],
    },

    onLoad() {
        // 最下边的位置
        this._bottom_posY = this.move_node_1.y - this.move_node_1.height;
        // 重置的位置
        this._reset_posY = this.move_node_2.y;
        // 起始的定位点
        this._startPosY = this.move_node_1.y;
        this._wheelCfg = [2, 3, 10, 5, 2, 3, 10, 5, 2, 3, 1000, 5];
    },

    async update(dt) {
        if (this._commonMove) {
            if (this._beginStop) {
                this._speed = 1500;
            }
            this.move_node_1.y -= dt * this._speed;
            this.move_node_2.y -= dt * this._speed;
            if (this.move_node_1.y <= this._bottom_posY) {
                this.move_node_1.y = this._reset_posY;
                if (this._beginStop) {
                    this._round--;
                    if (this._round <= 0) {
                        this._round = 0;
                        this._needStop = true;
                    }
                }
            }
            if (this.move_node_2.y <= this._bottom_posY) {
                this.move_node_2.y = this._reset_posY;
            }
            if (this._needStop) {
                if (this.move_node_1.y - this._endPosY <= 5 * 61) {
                    this._speed -= this._speedChangeInterval;
                    if (this._speed <= this._minSpeed) {
                        this._speed = this._minSpeed;
                    }
                }
                if (this.move_node_1.y <= this._endPosY) {
                    this.move_node_1.y = this._endPosY;
                    if (this._targetIndex >= 6) {
                        this.move_node_2.y = this.move_node_1.y + this.move_node_1.height;
                    } else {
                        this.move_node_2.y = this.move_node_1.y - this.move_node_1.height;
                    }
                    this._commonMove = false;
                    cc.vv.AudioManager.playEff("games/Poseidon/", "wheel_stop", true);
                    this.beishu.getComponent(sp.Skeleton).clearTracks();
                    this.beishu.getComponent(sp.Skeleton).setAnimation(0, "animation" + this._wheelCfg[this._targetIndex - 1], false);
                    let xuanzhongAnimation = "animation3";
                    if (this._wheelCfg[this._targetIndex - 1] === 1000) {
                        xuanzhongAnimation = "animation1";
                    } else if (this._wheelCfg[this._targetIndex - 1] === 10) {
                        xuanzhongAnimation = "animation2";
                    }
                    this.xuanzhong.active = true;
                    this.xuanzhong.getComponent(sp.Skeleton).clearTracks();
                    this.xuanzhong.getComponent(sp.Skeleton).setAnimation(0, xuanzhongAnimation, true);
                    this.xuanzhong.getComponent(sp.Skeleton).setCompleteListener(() => {
                        this.xuanzhong.active = false;
                    });
                    await this.awaitTime(1.5);
                    cc.vv.AudioManager.playEff("games/Poseidon/", "bonus_num", true);
                    cc.vv.gameData.GetSlotsScript().changeCoin();
                    await this.awaitTime(1);
                    this.reset();
                    cc.vv.gameData.GetSlotsScript().playGetCoinInFree();
                }
            }
        }
    },

    enterWheelGame() {
        // this._targetIndex = winIndex;
        this.node.active = true;
        // this._successCallback = successCallback;
        // this._caculateEndPosY();
        this.reset();
        this._commonMove = true;
    },

    exitWheelGame() {
        this._commonMove = false;
        this.node.active = false;
    },

    async startWheel(winIndex, successCallback) {
        this._targetIndex = winIndex;
        this._successCallback = successCallback;
        this._caculateEndPosY();
        this.waikuang.active = true;
        await this.awaitTime(1);
        this._beginStop = true;
        cc.vv.AudioManager.playEff("games/Poseidon/", "wheel", true);
    },

    reset() {
        this._commonMove = true;
        this._speed = 50;
        this._needStop = false;
        this._beginStop = false;
        this._round = 2;
        this.waikuang.active = false;
    },

    _caculateEndPosY() {
        this._endPosY = this._startPosY - (this._targetIndex - 6) * 61;
    },

    awaitTime(dt) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, dt);
        });
    }
});