/**墨西哥帅哥-符号表
 *
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() { },

    StartMove: function () {
        this._super();

        this.setCoinText({ coin: 0, jackpotId: null });
    },

    /**
     * 设置金币显示
     * @param {coin, jackpotId} data
     * @param rate
     */
    setCoinText(data, rate) {
        let coin_node = cc.find("coin_bg", this.node);
        let text = coin_node.getChildByName("coin");
        let minor = coin_node.getChildByName("minor");
        let major = coin_node.getChildByName("major");
        if (data.jackpotId) {
            switch (data.jackpotId) {
                case 2:
                    // minor
                    minor.active = true;
                    major.active = false;
                    break;
                case 3:
                    // major
                    minor.active = false;
                    major.active = true;
                    break;
                default:
                    minor.active = false;
                    major.active = false;
                    break;
            }
            coin_node.active = true;
            text.active = false;
        } else if (data.coin && data.coin !== 0) {
            minor.active = false;
            major.active = false;
            data.coin = rate ? data.coin * rate : data.coin;
            text.getComponent(cc.Label).string = Global.formatNumShort(data.coin);
            coin_node.active = true;
            text.active = true;
        } else {
            coin_node.active = false;
        }
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById: function (id, data) {
        this._super(id, data);
        if (data) {
            this.setCoinText(data);
        }
    },

    //停止旋转时刻
    //可做一些停止动作，比如scatter的缩放显示
    playStopAnimation: function () {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani) {
            if (this._showNode) {
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
            this._showNode.active = true
            if (cfg.symbol[id].stop_ani.name !== "") {
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].stop_ani.name, false);
                    if (id === cfg.wildId) {
                        // 如果是第一列，就直接播放音效，如果是第二列，要判断第一列是否有wild，有的话就播音效
                        let slots = cc.vv.gameData.GetSlotsScript();
                        if ((this._reelIdx === 0 && this._symbolIdx < cfg.row) ||
                            (this._reelIdx === 1 && slots.haveWildInReel(0))) {
                            cc.vv.AudioManager.playEff("games/Poseidon/", "symbol_wild", true);
                        }
                    }
                }
            }
        }
    },

    /**
     * 播放获得金币的动画
     */
    playGetCoinAnimation(callback) {
        this._showNode.runAction(cc.sequence(
            cc.scaleTo(0.2, 1.4),
            cc.callFunc(() => {
                let fangdahuo = cc.find("symbol_3/fangdahuo", this.node);
                fangdahuo.getComponent(sp.Skeleton).clearTracks();
                fangdahuo.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            }),
            cc.delayTime(0.5),
            cc.scaleTo(0.2, 1),
            cc.callFunc(() => {
                if (callback) {
                    callback();
                }
            })
        ));
        let coin_node = cc.find("coin_bg", this.node);
        coin_node.runAction(cc.sequence(
            cc.scaleTo(0.2, 1.4),
            cc.delayTime(0.5),
            cc.scaleTo(0.2, 1)
        ));
    },

    changeCoinNum(data, rate) {
        let shuzibao = cc.find("symbol_3/shuzibao", this.node);
        shuzibao.active = true;
        shuzibao.getComponent(sp.Skeleton).setToSetupPose();
        shuzibao.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        shuzibao.getComponent(sp.Skeleton).setCompleteListener(() => {
            shuzibao.active = false;
        })
        this.scheduleOnce(() => {
            this.setCoinText(data, rate);
        }, 0.1)
    },

    // update (dt) {},
});
