cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        wheel_script: null,
        _haveCheckWheel: false,
        _bgm: false,
        _playRoleAnimation: true,
        _roleAnimationTimer: 10,
    },

    Init: function () {
        this._super();
        if (cc.winSize.height / cc.winSize.width > 2.1) {
            cc.find("logo", this.node.parent).active = true;
        } else {
            cc.find("logo", this.node.parent).active = false;
        }

        this.node.parent.parent.getComponent("LMSlots_Puzzle").setCallback((freeInfo, chipGame) => {
            // 进入免费的逻辑
            cc.vv.gameData.SetTotalFree(freeInfo.freeCnt);
            cc.vv.gameData.SetFreeTime(freeInfo.freeCnt);
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.AudioManager.playEff("games/Poseidon/", "free_dialog_start_show", true);
            let spine = free_dialog.getChildByName("tcjingzi");
            spine.getComponent(sp.Skeleton).clearTracks();
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            spine.getComponent(sp.Skeleton).setCompleteListener((track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation") {
                    let enter_node = free_dialog.getChildByName("enter_node");
                    enter_node.active = true;
                    enter_node.scale = 0;
                    enter_node.runAction(cc.sequence(
                        cc.scaleTo(0.3, 1.2),
                        cc.scaleTo(0.1, 1)
                    ));
                    let btn_start = enter_node.getChildByName("btn_start");
                    btn_start.off("click");
                    let func = () => {
                        free_dialog.active = false;
                        enter_node.active = false;
                        cc.vv.AudioManager.playEff("games/Poseidon/", "popup_out", true);
                        this.scheduleOnce(() => {
                            this._showGameBg(true);
                            cc.find("role/jmnanren", this.node.parent).active = false;
                            this.wheel_script.enterWheelGame();
                        }, 2);
                        this.playQiepingAnim(() => {
                            Global.SlotsSoundMgr.playBgm("music_Poseidon_freespin_bg")
                            this.CanDoNextRound();
                        });
                    }
                    cc.vv.gameData.checkAutoPlay(btn_start, func);
                    btn_start.on("click", () => {
                        btn_start.stopAllActions();
                        func();
                    });
                    spine.getComponent(sp.Skeleton).clearTracks();
                    spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
                }
            });
        });
    },

    //重写
    StartMove: function () {
        this._super();
        let kuanghuo = cc.find("kuanghuo", this.node);
        kuanghuo.active = false;
        this.hideScatterBg();
        // if (!this._bgm) {
        //     this._bgm = true;
        //     cc.vv.AudioManager.playBgm("games/Poseidon/", "base_bgm", true);
        // }
        Global.SlotsSoundMgr.playNormalBgm()
    },

    //重写：小游戏取的数据不一样
    onMsgSpine: function (msg) {
        this._super(msg);
        if (this._getWildNum() >= 2) {
            this._bottomScript.ShowBtnsByState("moveing_1");
        }
    },

    //检查进入免费
    CheckEnterFreeGame() {
        let free_dialog = cc.find("free_dialog", this.node.parent);
        if (this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt === this._gameInfo.allFreeCnt) {
            cc.vv.AudioManager.playEff("games/Poseidon/", "bell", true);
            for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                let card = this._gameInfo.resultCards[i];
                if (card === this._cfg.scatterId) {
                    let symbol = this.GetSymbolByIdx(i + 1);
                    if (symbol) {
                        symbol.playWinAnimation();
                    }
                }
            }
            this.Backup();
            Global.SlotsSoundMgr.stopBgm();
            let self = this;
            this.scheduleOnce(() => {
                free_dialog.active = true;
                cc.vv.AudioManager.playEff("games/Poseidon/", "free_dialog_start_show", true);
                let spine = free_dialog.getChildByName("tcjingzi");
                spine.getComponent(sp.Skeleton).clearTracks();
                spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                spine.getComponent(sp.Skeleton).setCompleteListener((track) => {
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation") {
                        let enter_node = free_dialog.getChildByName("enter_node");
                        enter_node.active = true;
                        enter_node.scale = 0;
                        enter_node.runAction(cc.sequence(
                            cc.scaleTo(0.3, 1.2),
                            cc.scaleTo(0.1, 1)
                        ));

                        let btn_start = enter_node.getChildByName("btn_start");
                        btn_start.off("click");
                        let func = () => {
                            free_dialog.active = false;
                            enter_node.active = false;
                            cc.vv.AudioManager.playEff("games/Poseidon/", "popup_out", true);
                            this.scheduleOnce(() => {
                                this._showGameBg(true);
                                cc.find("role/jmnanren", this.node.parent).active = false;
                                this.wheel_script.enterWheelGame();
                            }, 2);
                            this.playQiepingAnim(() => {
                                Global.SlotsSoundMgr.playBgm("music_Poseidon_freespin_bg")
                                self.CanDoNextRound();
                            })
                        }
                        cc.vv.gameData.checkAutoPlay(btn_start, func);
                        btn_start.on("click", () => {
                            btn_start.stopAllActions();
                            func();
                        });
                        spine.getComponent(sp.Skeleton).clearTracks();
                        spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
                    }
                });
            }, 1);
            return true;
        } else if (this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0) {
            cc.vv.AudioManager.playEff("games/Poseidon/", "bell", true);
            for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                let card = this._gameInfo.resultCards[i];
                if (card === this._cfg.scatterId) {
                    let symbol = this.GetSymbolByIdx(i + 1);
                    if (symbol) {
                        symbol.playWinAnimation();
                    }
                }
            }
            this.scheduleOnce(() => {
                free_dialog.active = true;
                cc.vv.AudioManager.playEff("games/Poseidon/", "free_dialog_more_show", true);
                let spine = free_dialog.getChildByName("tcjingzi");
                spine.getComponent(sp.Skeleton).clearTracks();
                spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                spine.getComponent(sp.Skeleton).setCompleteListener((track) => {
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation") {
                        let extra_node = free_dialog.getChildByName("extra_node");
                        extra_node.active = true;
                        extra_node.scale = 0;
                        extra_node.runAction(cc.sequence(
                            cc.scaleTo(0.3, 1.2),
                            cc.scaleTo(0.1, 1),
                            cc.delayTime(1.5),
                            cc.callFunc(() => {
                                cc.vv.AudioManager.playEff("games/Poseidon/", "popup_out", true);
                                free_dialog.active = false;
                                extra_node.active = false;
                                this.CanDoNextRound();
                            })
                        ));
                        spine.getComponent(sp.Skeleton).clearTracks();
                        spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
                    }
                });
            }, 1);
            return true;
        } else {
            return false;
        }
    },

    //重写：免费游戏结束
    CheckExitFreeGame() {
        let total = this._gameInfo.freeWinCoin;
        let rest = cc.vv.gameData.GetFreeTime();
        if (total >= 0 && rest === 0 && cc.vv.gameData.GetTotalFree() > 0) {
            //结束了，显示免费游戏的总赢钱
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.AudioManager.playEff("games/Poseidon/", "free_dialog_collect_show", true);
            let result_node = free_dialog.getChildByName("result_node");
            let winNum = result_node.getChildByName("coin_bg").getChildByName("num");
            winNum.getComponent(cc.Label).string = "";
            let spine = free_dialog.getChildByName("tcjingzi");
            spine.getComponent(sp.Skeleton).clearTracks();
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            spine.getComponent(sp.Skeleton).setCompleteListener((track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation") {
                    result_node.active = true;
                    result_node.scale = 0;
                    result_node.runAction(cc.sequence(
                        cc.scaleTo(0.3, 1.2),
                        cc.scaleTo(0.1, 1),
                        cc.callFunc(() => {
                            winNum.active = true;
                            Global.doRoallNumEff(winNum, 0, total, 3, null, null, 0, true);
                        })
                    ));
                    let btn_collect = result_node.getChildByName("btn_collect");
                    btn_collect.off("click");
                    let func = async () => {
                        btn_collect.off("click");
                        winNum.stopAllActions();
                        if (Global.FormatCommaNumToNum(winNum.getComponent(cc.Label).string) < total) {
                            winNum.getComponent(cc.Label).string = Global.FormatNumToComma(total);
                            await cc.vv.gameData.awaitTime(0.4)
                        }
                        cc.vv.AudioManager.playEff("games/Poseidon/", "popup_out", true);
                        free_dialog.active = false;
                        result_node.active = false;
                        this.playQiepingAnim(() => {
                            Global.SlotsSoundMgr.stopBgm();
                            Global.SlotsSoundMgr.playNormalBgm()
                            this.ShowBottomWin(total, total, true, () => {
                                this.CanDoNextRound();
                            });
                        })
                        this.scheduleOnce(() => {
                            cc.find("role/jmnanren", this.node.parent).active = true;
                            this.wheel_script.exitWheelGame();
                            this._bottomScript.ShowFreeModel(false);
                            this._showGameBg(false);
                            this.Resume();
                        }, 2.2);
                    }
                    cc.vv.gameData.checkAutoPlay(btn_collect, func);
                    btn_collect.on("click", () => {
                        btn_collect.stopAllActions();
                        func();
                    });
                    spine.getComponent(sp.Skeleton).clearTracks();
                    spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
                }
            });
            return true;
        }
        return false;
    },

    async playQiepingAnim(callback) {
        let role = cc.find("Canvas/safe_node/role");
        role.active = false;
        let qieping = cc.find("Canvas/safe_node/qieping");
        cc.vv.AudioManager.playEff("games/Poseidon/", "music_Poseidon_GC_ShuiWoXuan", true);
        qieping.active = true
        qieping.getComponent(sp.Skeleton).clearTracks();
        qieping.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        await cc.vv.gameData.awaitTime(2.5);
        if (callback) {
            callback();
        }
        await cc.vv.gameData.awaitTime(0.4);
        qieping.active = false
        role.active = true;
    },

    //每列停止时间间隔
    //reelIdx:0开始
    GetReelStopInter: function (reelIdx) {
        // 如果前两列有wild，那么后三列就要延迟停止
        let nIter = this._cfg.reelStopInter || 0.6
        let wildNum = this._getWildNum();
        if (wildNum >= 2 && reelIdx >= 2) {
            let addCount = this._getAddCount();
            if (addCount === 1) {
                return nIter + 1.5 + (reelIdx - 1) * 2;
            } else if (addCount === 2) {
                return nIter + 3.5 + (reelIdx - 1) * 2;
            }
        }
        return reelIdx * nIter
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace: function () {
        this._super();
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        this._bottomScript.ShowBtnsByState("moveing_1");
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin();
        if (nWin > 0) {
            if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                // 免费中如果中奖了先开始转盘
                this.wheel_script.startWheel(this._gameInfo.coinExtraMult.id);
            } else {
                let kuanghuo = cc.find("kuanghuo", this.node);
                kuanghuo.active = false;
                let curWinNum = 0;
                if (this._getWildNum() >= 2) {
                    let gi = []
                    if (Array.isArray(this._gameInfo.winIdxs)) { gi = this._gameInfo.winIdxs }
                    // 后三列增高，如果中了bonus要添加金币
                    for (const index of gi/*this._gameInfo.winIdxs*/) {
                        let symbol = this.GetSymbolByIdx(index);
                        if (symbol.GetShowId() === this._cfg.bonusId && symbol.GetData()) {
                            symbol.playGetCoinAnimation(() => {
                                this._playBonusSpine();
                                curWinNum += symbol.GetData().coin;
                                this._bottomScript.SetWin(curWinNum);
                            });
                            cc.vv.AudioManager.playEff("games/Poseidon/", "bonus_result", true);
                            await this.awaitTime(2);
                        }
                    }
                }
                //显示中奖路线
                this.ShowWinTrace();
                this.ShowBottomWin(nWin - curWinNum, nWin, true, () => {
                    if (this.CheckExitFreeGame()) {
                    } else {
                        if (this.CheckSpecialReward()) {
                        } else {
                            this.CanDoNextRound();
                        }
                    }
                });
            }
        } else {
            if (this.CheckExitFreeGame()) {
            } else {
                if (this.CheckSpecialReward()) {
                } else {
                    // await this.awaitTime(0.5);
                    this.CanDoNextRound();
                }
            }
        }
    },

    //单列停止
    async OnReelSpinEnd(colIdx) {
        this._super(colIdx);
        // 后三列的升起逻辑
        if (colIdx === 1 && this._getWildNum() >= 2) {
            // 第二列旋转停止并且前两列wild数量>=2 ，那么后三列要升起
            // 先播放外框动画
            let kuanghuo = cc.find("kuanghuo", this.node);
            kuanghuo.active = true;
            kuanghuo.getComponent(sp.Skeleton).clearTracks();
            kuanghuo.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            cc.vv.AudioManager.playEff("games/Poseidon/", "reel_up", true);
            cc.vv.AudioManager.playEff("games/Poseidon/", "bonus_notify", true);
            await this.awaitTime(0.7);
            let addCount = this._getAddCount();
            let delay = addCount === 1 ? 0.5 : 1.5;
            kuanghuo.runAction(cc.sequence(
                cc.delayTime(delay),
                cc.callFunc(() => {
                    if (addCount === 1) {
                        kuanghuo.getComponent(sp.Skeleton).clearTracks();
                        kuanghuo.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
                    } else {
                        kuanghuo.getComponent(sp.Skeleton).clearTracks();
                        kuanghuo.getComponent(sp.Skeleton).setAnimation(0, "animation0", true);
                    }
                })
            ));
            for (let i = 2; i < 5; i++) {
                let reel = this._reels[i];
                if (addCount === 1) {
                    reel.AddCount(1, 0.5, 0.5);
                } else {
                    reel.node.runAction(cc.sequence(
                        cc.callFunc(() => {
                            reel.AddCount(1, 0.5, 0.5);
                        }),
                        cc.delayTime(1),
                        cc.callFunc(() => {
                            reel.AddCount(1);
                        })
                    ));
                }
            }
        }
        if ((colIdx === 2 || colIdx === 3) && this._getWildNum() >= 2) {
            cc.vv.AudioManager.playEff("games/Poseidon/", "bonus_notify", true);
        }
        // 如果有scatter，就显示加速背景
        let reel = this._reels[colIdx];
        if (reel.isHaveScatter()) {
            reel.setScatterBgVisible(true);
        }
        // 判断加速背景显示逻辑
        if (colIdx === 3) {
            // 判断前三列的scatter图标数量
            let scatterNum = 0;
            for (let i = 0; i < 3; i++) {
                let reel = this._reels[i];
                if (reel.isHaveScatter()) {
                    scatterNum++;
                }
            }
            if (scatterNum === 1) {
                let reel = this._reels[colIdx];
                if (!reel.isHaveScatter()) {
                    this.hideScatterBg();
                }
            }
            if (scatterNum === 0) {
                reel.setScatterBgVisible(false);
            }
        } else if (colIdx === 4) {
            // 判断前四列的scatter图标数量
            let scatterNum = 0;
            for (let i = 0; i < 4; i++) {
                let reel = this._reels[i];
                if (reel.isHaveScatter()) {
                    scatterNum++;
                }
            }
            // cc.log(scatterNum);
            if (scatterNum <= 1) {
                this.hideScatterBg();
            } else if (scatterNum === 2) {
                let reel = this._reels[colIdx];
                if (!reel.isHaveScatter()) {
                    this.hideScatterBg();
                }
            }
        }
    },

    SetSlotsResult: function (cards) {
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                if (cards[i] === this._cfg.bonusId) {
                    res.data = this.getBonusCoinNum(i + 1);
                }
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //根据服务端序号获取本地的symbol
    // 服务器是发的5行5列，所以计算的时候要按照5行来计算
    GetSymbolByIdx: function (idx) {
        let col = (idx - 1) % this._col
        let row = 5 - Math.floor((idx - 1) / this._col) - 1
        return this._reels[col].GetSymbolByRow(row)
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        if (bFree) {
            let total = cc.vv.gameData.GetTotalFree();
            let rest = cc.vv.gameData.GetFreeTime();
            //显示免费次数
            this._bottomScript.ShowFreeModel(true, total - rest, total);
            let nTotal = cc.vv.gameData.GetTotalFreeWin();
            this._bottomScript.SetWin(nTotal);
            cc.find("role/jmnanren", this.node.parent).active = false;
            cc.find("wheel", this.node.parent).getComponent("Poseidon_Wheel").enterWheelGame();
            // cc.vv.AudioManager.playBgm("games/Poseidon/", "music_Poseidon_freespin_bg", true);
            Global.SlotsSoundMgr.playBgm("music_Poseidon_freespin_bg")
            this.CanDoNextRound();
        }
        else {
            this._bottomScript.ShowFreeModel(false)
        }
        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if (normalFree) { //存在免费游戏背景才执行下面的逻辑
            if (normalBg) {
                normalBg.active = !bFree
            }
            normalFree.active = bFree
        }
        cc.find("LMSlots_Collect_Puzzle", this.node.parent).active = !bFree;
    },

    update(dt) {
        if (this._stopTime > 0) {
            this._stopTime = this._stopTime - dt
            if (this._stopTime <= 0) { //空转时间到了
                if (this.CanStopSlot()) {//满足开始停止的条件
                    if (this._getWildNum() < 2) {
                        this._bottomScript.ShowBtnsByState("moveing_2")
                    }
                    //倒计时完，设置一次
                    for (let i = 0; i < this._reels.length; i++) {
                        let item = this._reels[i]
                        let reelStopInterv = this.GetReelStopInter(i)
                        item.StopMove(reelStopInterv)
                    }
                }
                else {
                    //如果没有结果,则延迟一帧
                    this._stopTime = dt
                }
            }
        }
        if (this._playRoleAnimation) {
            this._roleAnimationTimer -= dt;
            if (this._roleAnimationTimer <= 0) {
                this._playRoleAnimation = false;
                this._roleAnimationTimer = 10;
                let jmnanren = cc.find("role/jmnanren", this.node.parent);
                let animationName = "";
                if (Math.random() < 0.5) {
                    animationName = "Idle";
                } else {
                    animationName = "Idle";
                }
                jmnanren.getComponent(sp.Skeleton).clearTracks();
                jmnanren.getComponent(sp.Skeleton).setAnimation(0, animationName, true);
                // jmnanren.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                //     let name = track.animation ? track.animation.name : "";
                //     if (name === "Idle" || name === "Idle") {
                //         jmnanren.getComponent(sp.Skeleton).clearTracks();
                //         jmnanren.getComponent(sp.Skeleton).setAnimation(0, "skill", true);
                //         this._playRoleAnimation = true;
                //     }
                // });
            }
        }
    },

    setWheelScripts(script) {
        this.wheel_script = script;
    },

    /**
     * 通过索引获取bonus图标上应该显示的数量
     * @param {number} index 索引，从1开始
     */
    getBonusCoinNum(index) {
        let idx = this._gameInfo.coinIdxs.indexOf(index);
        if (idx !== -1 && idx < this._gameInfo.coinList.length) {
            return this._gameInfo.coinList[idx];
        }
    },

    changeCoin() {
        let gi = []
        if (Array.isArray(this._gameInfo.winIdxs)) { gi = this._gameInfo.winIdxs }
        for (const index of gi/*this._gameInfo.winIdxs*/) {
            let symbol = this.GetSymbolByIdx(index);
            if (symbol.GetShowId() === this._cfg.bonusId && symbol.GetData()) {
                symbol.changeCoinNum(symbol.GetData(), this._gameInfo.coinExtraMult.mult);
            }
        }
    },

    async playGetCoinInFree(callback) {
        let kuanghuo = cc.find("kuanghuo", this.node);
        kuanghuo.active = false;
        let curWinNum = 0;
        if (this._getWildNum() >= 2) {
            let gi = []
            if (Array.isArray(this._gameInfo.winIdxs)) { gi = this._gameInfo.winIdxs }
            // 后三列增高，如果中了bonus要添加金币
            for (const index of gi/*this._gameInfo.winIdxs*/) {
                let symbol = this.GetSymbolByIdx(index);
                if (symbol.GetShowId() === this._cfg.bonusId && symbol.GetData()) {
                    symbol.playGetCoinAnimation(() => {
                        this._playBonusSpine();
                        curWinNum += symbol.GetData().coin;
                        this._bottomScript.ShowWin(symbol.GetData().coin, 1, null, null);
                    });
                    await this.awaitTime(2);
                }
            }
        }
        //显示底部赢钱
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() !== cc.vv.gameData.GetTotalFree() > 0) {
            this.ShowWinTrace();
        }
        let nWin = cc.vv.gameData.GetGameWin();
        this.ShowBottomWin(nWin - curWinNum, cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            if (this.CheckExitFreeGame()) {
                this._bottomScript.ShowFreeModel(false);
            } else {
                if (this.CheckSpecialReward()) {

                } else {
                    this.CanDoNextRound();
                }
            }
        });
    },

    hideScatterBg() {
        let r = []
        if (Array.isArray(this._reels)) { r = this._reels }
        for (const reel of r/*this._reels*/) {
            reel.setScatterBgVisible(false);
        }
    },

    /**
     * 判断一列是否有wild
     * @param reelIdx
     * @returns {boolean}
     */
    haveWildInReel(reelIdx) {
        let reel = this._reels[reelIdx];
        if (reel) {
            for (let i = 0; i < this._cfg.row; i++) {
                let symbol = reel.GetSymbolByRow(i);
                if (symbol && symbol.GetShowId() === this._cfg.wildId) {
                    return true;
                }
            }
        }
        return false;
    },

    /**
     * 获取前两列的wild数量
     */
    _getWildNum() {
        let wildNum = 0;
        let one = 0;
        let two = 0;
        if (this._gameInfo) {
            for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                const id = this._gameInfo.resultCards[i];
                if (i % 5 === 0 && id === this._cfg.wildId && one === 0) {
                    one = 1;
                    wildNum++;
                }
                if (i % 5 === 1 && id === this._cfg.wildId && two === 0) {
                    two = 1;
                    wildNum++;
                }
            }
        }
        return wildNum;
    },

    _playBonusSpine() {
        let spine = cc.find("bonus_node/bouns_sj_01", this.node.parent);
        if (spine) {
            spine.active = true;
            spine.position = spine.parent.convertToNodeSpaceAR(this._bottomScript.getWinLabelNor().convertToWorldSpaceAR(cc.v2(0, 0)));
            spine.getComponent(sp.Skeleton).clearTracks();
            spine.getComponent(sp.Skeleton).setToSetupPose();
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            spine.getComponent(sp.Skeleton).setCompleteListener(() => {
                spine.active = false;
            });
        }
    },

    /**
     * 获取需要升高几行
     */
    _getAddCount() {
        let addCount = 0;
        if (this._gameInfo) {
            for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                if (i >= 10) {
                    break;
                }
                const id = this._gameInfo.resultCards[i];
                if (id !== 20) {
                    if (i <= 4) {
                        addCount = 2;
                    } else {
                        addCount = 1;
                    }
                    break;
                }
            }
        }
        return addCount;
    },

    _showGameBg: function (bFree) {
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        normalBg.active = !bFree
        normalFree.active = bFree
    },

    awaitTime(time) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, time);
        });
    },
});
